  "version": "1.2.0",
  "description": "Slice and filter big log files from the command line",
  "type": "module",
  "bin": { "logslice": "bin/logslice.mjs" },
  "scripts": {
    "test": "node --test test/"
  },
  "license": "MIT"
}

