import readline from "node:readline";
import { fail } from "./errors.mjs";
import { formatLine } from "./output.mjs";
import { parseStamp, parseWhen } from "./time.mjs";

function parseArgs(argv) {
  const opts = { grep: null, since: null, format: "text", file: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--grep" || a === "--since" || a === "--format") {
      const value = argv[++i];
      if (value === undefined) fail(`missing value for ${a}`);
      if (a === "--grep") opts.grep = value;
      else if (a === "--since") opts.since = value;
      else opts.format = value;
    } else if (a.startsWith("-")) {
      fail(`bad flag ${a}`);
    } else opts.file = a;
  }
  return opts;
}

export async function main(argv) {
  const opts = parseArgs(argv);
  if (!opts.file) {
    console.error("usage: logslice [--grep <regex>] [--since <time>] [--format text|json] <file>");
    process.exit(1);
  }
  if (opts.format !== "text" && opts.format !== "json") fail(`bad flag --format ${opts.format}`);
  let re = null;
  if (opts.grep) {
    try {
      re = new RegExp(opts.grep);
    } catch {
      fail(`bad flag --grep ${opts.grep}`);
    }
  }
  const since = opts.since ? parseWhen(opts.since) : null;
  if (opts.since && !since) fail(`bad flag --since ${opts.since}`);
  const input = fs.createReadStream(opts.file);
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  let matched = 0;
  try {
    for await (const line of rl) {
      if (re && !re.test(line)) continue;
      if (since) {
        const at = parseStamp(line);
        if (at && at < since) continue;
      }
      matched++;
      process.stdout.write(formatLine(line, opts.format) + "\n");
    }
  } catch (err) {
    process.stderr.write(`logslice: ${err.message}\n`);
    return 1;
  }
  return matched > 0 ? 0 : 1;
}

/** Report bad user input and exit with status 2 (usage error). */
export function fail(message) {
  process.stderr.write(`logslice: ${message}\n`);
  process.exit(2);
}

