import { randomBytes } from "node:crypto";

const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

/** A 26-character ULID-style id: 10 characters of time, then 16 random ones. */
export function newId(now = Date.now()): string {
  let time = "";
  let t = now;
  for (let i = 0; i < 10; i++) {
    time = ALPHABET[t % 32] + time;
    t = Math.floor(t / 32);
  }
  const bytes = randomBytes(16);
  let rand = "";
  for (const b of bytes) rand += ALPHABET[b % 32];
  return time + rand;
}

import { Router } from "express";
import { query } from "../db.js";
import { newId } from "../lib/ids.js";

export const parcels = Router();

interface ParcelRow {
  id: string;
  tracking_number: string;
  weight_grams: number;
  status: string;
  created_at: Date;
}

function toJson(row: ParcelRow) {
  return {
    id: row.id,
    trackingNumber: row.tracking_number,
    weightGrams: row.weight_grams,
    status: row.status,
    createdAt: row.created_at.toISOString(),
  };
}

parcels.get("/", async (_req, res) => {
  const rows = await query<ParcelRow>("SELECT * FROM parcels ORDER BY created_at DESC");
  res.json({ parcels: rows.map(toJson) });
});

parcels.get("/:id", async (req, res) => {
  const rows = await query<ParcelRow>("SELECT * FROM parcels WHERE id = $1", [req.params.id]);
  res.json(rows[0] ? toJson(rows[0]) : null);
});

parcels.post("/", async (req, res) => {
  const id = newId();
  const { trackingNumber, weightGrams } = req.body;
  await query("INSERT INTO parcels (id, tracking_number, weight_grams, status) VALUES ($1, $2, $3, 'created')", [id, String(trackingNumber).toUpperCase(), weightGrams]);
  res.status(201).json({ id });
});

import pg from "pg";

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

export async function query<T = unknown>(sql: string, params: unknown[] = []): Promise<T[]> {
  const res = await pool.query(sql, params);
  return res.rows as T[];
}

import { httpGet } from "../lib/http.js";

export class CarrierClient {
  constructor(private apiKey: string, private baseUrl = "https://api.shipcarrier.example") {}

  /** Latest status of one parcel */
  getStatus(tracking: string): Promise<unknown> {
    return httpGet(`${this.baseUrl}/v2/status/${encodeURIComponent(tracking)}`, { headers: { "X-Api-Token": this.apiKey } });
  }

  /** Every scan event of one parcel */
  getEvents(tracking: string): Promise<unknown> {
    return httpGet(`${this.baseUrl}/v2/events/${encodeURIComponent(tracking)}`, { headers: { "X-Api-Token": this.apiKey } });
  }
}

CREATE TABLE parcels (
  id              text PRIMARY KEY,
  tracking_number text NOT NULL UNIQUE,
  weight_grams    integer NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);

