node --input-type=module << 'EOF'
import express from "express";
import http from "node:http";

const app = express();
const parcels = express.Router();
parcels.get("/", (req, res) => res.json({ route: "list", url: req.url, params: req.params }));
parcels.get("/:id", (req, res) => res.json({ route: "id", url: req.url, params: req.params, originalUrl: req.originalUrl }));
parcels.get("/lookup/:tracking", (req, res) => res.json({ route: "lookup", params: req.params }));
app.use("/v1/parcels", parcels);

const server = app.listen(0, async () => {
  const port = server.address().port;
  const paths = [
    "/v1/parcels/ABC123",
    "/v1/parcels/AB%20123",
    "/v1/parcels/AB+123",
    "/v1/parcels/lookup/AB%20123",
    "/v1/parcels/lookup/AB+123",
    "/v1/parcels/by-tracking/AB%20123",
    "/v1/parcels?trackingNumber=AB%20123",
    "/v1/parcels/AB%20123/status",
  ];
  for (const p of paths) {
    const res = await fetch(`http://127.0.0.1:${port}${p}`);
    const text = await res.text();
    console.log(res.status, p, "=>", text.slice(0, 200));
  }
  // raw request with literal space
  await new Promise((resolve) => {
    const req = http.request({ hostname: "127.0.0.1", port, path: "/v1/parcels/AB 123", method: "GET" }, (res) => {
      let d = "";
      res.on("data", (c) => d += c);
      res.on("end", () => { console.log(res.statusCode, "literal space", "=>", d.slice(0, 200)); resolve(); });
    });
    req.on("error", (e) => { console.log("literal space error", e.message); resolve(); });
    req.end();
  });
  server.close();
});
EOF

