 * replies that report a failed attempt score 0.69 to 0.99, attempts carried out 0.19 or less, bug fixes 0.12 or less;
 * replies that decline from reading the code, or ask which way to go, fall on both sides.
 */
export const REPLY_MIN = 0.5;

const QUESTION_START = /^(why|how|what|where|which|when|who|whose|whom|can|could|would|should|does|do|is|are|did|was|were|will|explain|tell me|help me|show me|any idea|anyone know|find out|investigate|debug|diagnose|look into|check why|figure out)\b/i;

// Bug-report vocabulary. A bare 3-digit number is not enough ("under 500 KB", "port 443"); a 4xx/5xx counts only in an
// HTTP context: "returns 500", "HTTP 404", "status 503", "502 error".
const BUG_REPORT = /\b(fails?|failing|failed|broken|breaks?|crash(es|ed|ing)?|error|exception|flaky|stale|wrong|incorrect|doesn'?t work|not working|isn'?t working|won'?t (start|build|load|compile)|hangs?|timeout|times out|returns? (a |an )?[45]\d\d|(http|status|code|with an?) [45]\d\d|[45]\d\d (error|response|status)|bug|regression|leak|slow)\b|\b[A-Z][a-zA-Z]*Error\b/i;

/**
 * Does the user's message invite an answer from the assistant? Only then is the assistant reply part of the state:
 * a statement from the user is the memory, and the assistant's acknowledgement, options, or summary never is.
 * It is a keyword heuristic, and deliberately broad. True when any of:
 * - the message ends with `?`, or its first line contains one;
 * - it starts with a question or investigation word (why, how, what, do, is, will, can, explain, debug, look into, …);
 * - its first 400 characters contain bug-report vocabulary (error, fails, broken, crash, flaky, stale, wrong, slow,
 *   timeout, bug, regression, leak, a `…Error` name, or an HTTP-context 4xx/5xx such as "returns 500").
 * So "Use Sentry for error reporting." also sends the reply; the content_source question then decides which side
 * the memory comes from, and only bug, architecture and dead-end may come from the assistant.
 */
export function looksLikeQuestion(user: string): boolean {
  const t = user.trim();
  if (!t) return false;
  if (/\?\s*$/.test(t) || /\?/.test(t.split("\n")[0] ?? "")) return true;
  if (QUESTION_START.test(t)) return true;
  return BUG_REPORT.test(t.slice(0, 400));
}

// An attempt and how it ended, in the assistant's words: "I tried …", "reverted", "rolled back", "didn't help".
const ATTEMPT_REPORT = /\b(tried|attempted|reverted|rolled (it |that |this |them )?back|backed (it|that|this|them) out|switched (it |that |them )?back|went back to|gave up on|abandoned|(didn't|did not|doesn't|does not) (work|help)|made no difference|no luck|still (fails|failed|failing))\b/i;

/**
 * Does the assistant reply report an attempt that ended (tried, reverted, rolled back, didn't help)? Then the reply is
 * part of the state even when the user made a statement: a dead end is usually found by the assistant while it works
 * ("Try keepalive" → "I tried keepalive at 10 s; the server answered GOAWAY, so I removed it"). A keyword heuristic, like
 * `looksLikeQuestion`; the content_source question still decides which side a memory comes from.
 */
export function reportsAnAttempt(assistant: string): boolean {
  return ATTEMPT_REPORT.test(assistant);
}

/** Distinct keywords (see `keywords`) a turn and a live dead-end line must share for the turn to be about that dead end. */
export const DEAD_END_TOPIC_MIN = 3;

/**
 * Is the turn (the user message and the reply) about a live dead-end line: at least DEAD_END_TOPIC_MIN keywords in
 * common with one? Then the reply is part of the state, because Claude may have made the dead end work, which only the
 * reply shows ("Make X work" → "X works now: …"). Only live dead ends count, and only the works-now question lets the
 * reply supersede anything, and only a dead-end line (docs/dead-ends.md).
 */
export function aboutADeadEnd(text: string, memories: Pick<Memory, "kind" | "text">[]): boolean {
  const kw = keywords(text);
  return memories.some((m) => {
    if (m.kind !== "dead-end") return false;
    let n = 0;
    for (const w of keywords(m.text)) if (kw.has(w) && ++n >= DEAD_END_TOPIC_MIN) return true;
    return false;
  });
}

/** The borderline rule: which conditions say tier 1 is unsure. Pure, so it is testable and shown by `why`. */
export function borderlineReasons(t1: Pick<TierAnswers, "nouls" | "importanceConfidence"> & { kindConfidence?: number }, rule: BorderlineRule): string[] {
  const reasons: string[] = [];
  // Injection is the max over the tier-1 injection nouls (currently one: the broad noul).

    what: "A choice between alternatives was made for this project: library, approach, naming, process.",
    not_for: "Rules with must/never (constraint), taste (preference), deferred work (todo).",
    examples: ["We'll use Postgres instead of SQLite.", "Go with tRPC for the API.", "Decided to drop Redux."],
  },
  constraint: {
    what: "A hard rule or limit the project must respect: compatibility, security, performance, policy.",
    not_for: "Soft taste or style (preference), a one-off choice with no rule (decision).",
    examples: ["Must support Node 20.", "Never call the payments API from the client.", "Bundle must stay under 200 KB."],
  },
  preference: {
    what: "How the user likes things done: style, tone, tools, conventions. Softer than a constraint.",
    not_for: "Hard rules with consequences (constraint), product decisions (decision).",
    examples: ["Prefer named exports.", "I like short commit messages.", "Use pnpm, not npm."],
  },
  bug: {
    what: "A bug, its root cause, or a fix that was found while working.",
    not_for: "Planned features or refactors (todo), how the system is laid out (architecture), a fix found after another attempt failed, or an approach dropped or replaced because it failed (dead-end).",
    examples: ["The flaky test was caused by a shared temp dir.", "Race in the cache invalidation on logout."],
  },
  architecture: {
    what: "A fact about how the system is structured: modules, data flow, services, boundaries, where things live.",
    not_for: "A choice being made right now (decision), a failure (bug).",
    examples: ["Auth lives in packages/auth and is called by the gateway.", "Events go through one Kafka topic per tenant."],
  },
  todo: {
    what: "Work that is explicitly deferred or promised for later.",
    not_for: "Work already done (bug fix, decision), rules (constraint).",
    examples: ["Add rate limiting before launch.", "TODO: migrate the cron job to a queue."],
  },
  "dead-end": {
    what: "An approach that was tried for this project and failed or was dropped, with the reason it did not work, including one a listed memory states that is now dropped or replaced; also when another approach, or a fix, then worked.",
    not_for: "A failure that a retry fixed, a test written to fail first, options discussed but not tried, a change of taste (decision or preference), an approach that failed before and works now (decision).",
    examples: ["Moving the job queue to SQS added 300 ms per job, so it was rolled back.", "A CDN cache in front of the API served stale carts to logged-in users, so it came out again."],
  },
  none: {
    what: "Nothing in the message is worth remembering for this project: greetings, thanks, status chatter, generic questions, or content unrelated to the project.",
    not_for: "Any message that states a decision, rule, preference, bug, structure fact, or deferred work.",
    examples: ["thanks, great work!", "What's the difference between Map and WeakMap?", "lol"],
  },
};

    replyNoul,
    usage: { inputTokens: both.inputTokens + extra.inputTokens, outputTokens: both.outputTokens + extra.outputTokens },
    cacheHit: chosen.cacheHit && Boolean((asked as { cacheHit?: boolean }).cacheHit),
    reason: `${chosen.reason} [reply question: ${replyNoul.toFixed(2)}${read ? ", the reply read" : own ? ", a dead end from the user's message kept" : ", the reply not read"}]`,
  };
}

// A request to try or change something, in the user's words: an instruction verb at the start, after an opener ("ok,",
// "please", "can you", "go ahead and") or in "let's …", "we're going to …", "we'll …". The verbs are the ones such
// requests use for code (try, see if, switch, replace, use, turn on, add, bump, make, run, …); a statement of a
// decision ("For search we'll adopt Meilisearch.") or a to-do ("Note for later: …") is not one. Built from everyday
// English and the dev set's prompts, not from any held-out set.
const REQUEST = new RegExp(
  "^(?:(?:ok(?:ay)?|right|so|now|next|then|also|and|please|hey|hi|great|good|thanks|thank you|yes|no|sure|actually|quick one)[,.:!]?\\s+)*(?:(?:can|could|would|will) you\\s+|(?:i(?:'d| would) like (?:you )?to|i want (?:you )?to|we should|we need to|you should)\\s+)?(?:please\\s+)?(?:go ahead and\\s+)?(?:(?:let'?s|let us|we(?:'re| are) going to|we(?:'ll| will))\\s+\\w+|try|see (?:if|whether)|check (?:if|whether)|test (?:if|whether)|find out (?:if|whether)|give\\b.{1,60}?\\ba (?:go|try|shot|spin|whirl)|have a (?:go|try|crack|stab)|take a (?:crack|stab|run)|experiment with|attempt|switch|swap|replace|move|migrate|convert|change|rewrite|refactor|port|use|adopt|introduce|turn (?:on|off)|enable|disable|add|remove|drop|delete|bump|upgrade|downgrade|update|pin|raise|lower|increase|reduce|cut|split|merge|inline|extract|rename|cache|wire|hook up|make|set|run|put|install|configure|flip|point|route|wrap|batch|parallelise|parallelize)\\b",
  "i",
);

/**
 * Does the user's message read as a request to try or change something? Then the reply question is asked (0.6.6):
 * only such a turn can end in an attempt that failed, and on the 66-turn benchmark set it is 4 turns beyond the 14
 * whose reply the state already holds, where asking on every turn would send the reply on all 66.
 */
export function looksLikeRequest(user: string): boolean {
  return REQUEST.test(user.trim());
}

/** Whether the reply question is asked for this turn, given the user's message (the state not holding the reply). */
export function askAboutReply(userMessage: string): boolean {
  return looksLikeRequest(userMessage);
}

