node --input-type=module << 'EOF'
import express from "express";
import net from "node:net";

const app = express();
const parcels = express.Router();
parcels.get("/:id", (req, res) => res.json({ id: req.params.id, url: req.url }));
app.use("/v1/parcels", parcels);
app.use((err, req, res, next) => {
  console.log("ERR", err.status, err.message);
  res.status(err.status || 500).json({ error: err.message });
});

const server = app.listen(0, async () => {
  const port = server.address().port;
  const raws = [
    "GET /v1/parcels/AB%20123 HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n",
    "GET /v1/parcels/AB 123 HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n",
    "GET /v1/parcels/AB+123 HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n",
    "GET /v1/parcels/lookup/AB%20123 HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n",
    "GET /tracking/AB%20123 HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n",
  ];
  for (const msg of raws) {
    const first = msg.split("\r\n")[0];
    const resp = await new Promise((resolve) => {
      const sock = net.connect(port, "127.0.0.1", () => sock.write(msg));
      let data = "";
      sock.on("data", (c) => data += c);
      sock.on("end", () => resolve(data));
      sock.on("error", (e) => resolve("SOCKET " + e.message));
    });
    const head = String(resp).split("\r\n").slice(0, 1).join(" | ");
    const body = String(resp).split("\r\n\r\n")[1]?.slice(0, 180);
    console.log("\nREQ", first);
    console.log(head, body);
  }
  server.close();
});
EOF

